using Microsoft.Xna.Framework;
namespace BluewaterHaul;
public static class CityRules {
 // 26 seconds green, 3 amber, 1 all-red per approach pair.
 public static int Signal(float seconds,bool northSouth){float phase=(seconds+(northSouth?0:30))%60;if(phase<0)phase+=60;return phase<26?2:phase<29?1:0;}
 public static string Routine(float hour,int shift=0){hour=(hour+shift+24)%24;return hour<7||hour>=21?"Home":hour<9?"Commute":hour<12?"Work":hour<14?"Lunch":hour<17?"Work":hour<19?"Errands":"Home";}
 public static bool NorthSouth(Vector2 direction)=>Math.Abs(direction.Y)>=Math.Abs(direction.X);
}
public sealed class TrafficLink {public int From,To;public float Width,Limit;public bool OneWay;}
public sealed class TrafficAgent {public int Id;public TrafficLink Link=null!;public float Distance,Speed,Wait;public Vector2 Point;public float Yaw;public string Kind="car";public float Damage,BurnTime;public bool Destroyed;}
public sealed class Citizen {public int Id;public Vector2 Home,Work,Errand,Point;public List<Vector2> Route=[];public int Step;public string Activity="";public float Wait,Stride,Pause;public int Shift;}
