 Vector2 SidewalkPoint(Vector2 point){var snap=walkRouter.Snap(point);var d=walkRouter.Nodes[snap.Segment.B]-walkRouter.Nodes[snap.Segment.A];d.Normalize();var right=new Vector2(-d.Y,d.X);float offset=Math.Clamp(sidewalkWidths.GetValueOrDefault(snap.Segment.Name,7)/2+1.1f,3.7f,10);foreach(float side in new[]{1f,-1f}){var p=snap.Point+right*offset*side;if(!Blocked(p))return p;}return snap.Point;}
 void UpdateStreetLife(float dt){cityStreamTimer-=dt;if(cityStreamTimer<=0){StreamStreetLife();cityStreamTimer=3;}cityAccumulator+=dt;if(cityAccumulator<.1f)return;float step=Math.Min(cityAccumulator,.2f);cityAccumulator=0;float seconds=state.Hour*120;foreach(var t in traffic){if(t.Destroyed||bodyMotion.TryGetValue(-10000-t.Id,out var physical)&&physical.Hold>0)continue;if(Vector2.DistanceSquared(t.Point,OutsidePosition)>1800*1800)continue;var start=carRouter.Nodes[t.Link.From];var end=carRouter.Nodes[t.Link.To];float length=Vector2.Distance(start,end),remaining=length-t.Distance;var dir=Vector2.Normalize(end-start);bool red=signalNodes.Contains(t.Link.To)&&CityRules.Signal(seconds,CityRules.NorthSouth(dir))!=2;bool stop=red&&remaining<14;float target=stop?0:t.Link.Limit;if(remaining<18)target=Math.Min(target,4);
   foreach(var other in traffic){if(other==t||Vector2.DistanceSquared(other.Point,t.Point)>32*32)continue;var delta=other.Point-t.Point;float ahead=Vector2.Dot(delta,dir),side=Math.Abs(Vector2.Dot(delta,new Vector2(-dir.Y,dir.X)));if(ahead>0&&ahead<VehicleSpec.For(t.Kind).Length/2+VehicleSpec.For(other.Kind).Length/2+5&&side<2.4f){target=0;break;}}
   foreach(var vehicle in fleet){var delta=vehicle.Point-t.Point;float ahead=Vector2.Dot(delta,dir);if(ahead>0&&ahead<VehicleSpec.For(t.Kind).Length/2+VehicleSpec.For(vehicle.Kind).Length/2+6&&Math.Abs(Vector2.Dot(delta,new Vector2(-dir.Y,dir.X)))<2.5f)target=0;}
   if(interior==0&&!driving&&Vector2.DistanceSquared(t.Point,position)<100)target=0;if(citizens.Any(c=>Vector2.DistanceSquared(c.Point,t.Point)<64&&Vector2.Dot(c.Point-t.Point,dir)>0))target=0;
   t.Speed=MathHelper.Lerp(t.Speed,target,Math.Min(1,step*(target<t.Speed?4:1)));if(stop&&remaining<12)t.Speed=0;float next=t.Distance+t.Speed*step;var q=CityPoint(t.Link,next);if(VehicleBlocked(q,t.Yaw,-1,VehicleSpec.For(t.Kind))||TrafficBlocked(q,t.Yaw,VehicleSpec.For(t.Kind),t)){t.Speed=0;t.Wait+=step;}else{t.Distance=next;t.Point=q;t.Wait=0;}if(stop){trafficStops++;t.Wait+=step;}
   if(t.Distance>=length-.5f&&cityLinks.TryGetValue(t.Link.To,out var options)){var onward=options.Where(l=>l.To!=t.Link.From).ToList();if(onward.Count==0)onward=options;var nextLink=onward[cityRandom.Next(onward.Count)];var np=CityPoint(nextLink,0);if(!VehicleBlocked(np,LinkYaw(nextLink),-1,VehicleSpec.For(t.Kind))&&!TrafficBlocked(np,LinkYaw(nextLink),VehicleSpec.For(t.Kind),t)){t.Link=nextLink;t.Distance=0;t.Point=np;t.Yaw=LinkYaw(nextLink);}}
