 }
 void StreamStreetLife(){var origin=OutsidePosition;var nearby=citySpawnLinks.Where(l=>Vector2.DistanceSquared(carRouter.Nodes[l.From],origin)>500*500&&Vector2.DistanceSquared(carRouter.Nodes[l.From],origin)<1300*1300).ToList();if(nearby.Count==0)return;foreach(var t in traffic.Where(t=>Vector2.DistanceSquared(t.Point,origin)>1800*1800).Take(8)){var link=nearby[cityRandom.Next(nearby.Count)];float dist=Vector2.Distance(carRouter.Nodes[link.From],carRouter.Nodes[link.To])*.4f;var q=CityPoint(link,dist);float heading=LinkYaw(link);if(VehicleBlocked(q,heading,-1,VehicleSpec.For(t.Kind))||TrafficBlocked(q,heading,VehicleSpec.For(t.Kind),t))continue;t.Link=link;t.Distance=dist;t.Point=q;t.Yaw=heading;t.Speed=0;t.Wait=0;}
  var homes=world.Buildings.Where(b=>b.Enterable&&Vector2.DistanceSquared(Geo.V(b.Center),origin)>700*700&&Vector2.DistanceSquared(Geo.V(b.Center),origin)<1300*1300).ToList();if(homes.Count==0)return;foreach(var c in citizens.Where(c=>Vector2.DistanceSquared(c.Point,origin)>1600*1600).Take(8)){var b=homes[cityRandom.Next(homes.Count)];var home=SidewalkPoint(Geo.V(b.Center));if(Blocked(home)||PedestrianVehicleBlocked(home))continue;c.Home=home;c.Point=home;c.Work=SidewalkPoint(home+new Vector2(300,200));c.Errand=SidewalkPoint(home+new Vector2(-180,250));c.Route=[];c.Step=0;c.Activity="";c.Wait=0;}
 }
 bool CitizenBlocked(Vector2 p,float heading,VehicleSpec spec){var f=VehiclePhysics.Forward(heading);var r=new Vector2(-f.Y,f.X);return citizens.Any(c=>Math.Abs(Vector2.Dot(c.Point-p,f))<spec.Length/2+.45f&&Math.Abs(Vector2.Dot(c.Point-p,r))<spec.Width/2+.45f);}
