  foreach(var c in citizens){if(knockdowns.ContainsKey(c.Id))continue;if(Vector2.DistanceSquared(c.Point,position)>260*260)continue;float y=GroundHeight(c.Point);var p=c.Point;var shirt=new Color(65+c.Id%4*35,75+c.Id%3*30,95+c.Id%5*20);m.Box(Geo.V3(p-new Vector2(.2f),y+.65f),Geo.V3(p+new Vector2(.2f),y+1.35f),shirt);m.Box(Geo.V3(p-new Vector2(.16f),y+1.35f),Geo.V3(p+new Vector2(.16f),y+1.7f),new(204,160,126));float swing=c.Step<c.Route.Count?MathF.Sin(c.Stride*8)*.13f:0;foreach(float side in new[]{-1f,1f})m.Box(new(p.X+side*.12f-.07f,y,p.Y+side*swing-.08f),new(p.X+side*.12f+.07f,y+.65f,p.Y+side*swing+.08f),new(43,64,86));}
