 Citizen? NearCitizen()=>interior==0&&!driving?citizens.Where(c=>Vector2.DistanceSquared(c.Point,position)<9).MinBy(c=>Vector2.DistanceSquared(c.Point,position)):null;
 void TalkCitizen(Citizen c){string[] lines=["The light turns green eventually. So does the bread in my glovebox.","I am on my way to work. My enthusiasm took a different route.","My neighbour repaired his pickup with a shelf bracket. Now it has storage.","Lunch break. I have twelve minutes and a sandwich with structural problems.","If you need directions, ask someone who has not been detoured since Tuesday."];Tell(new[]{"Gord","Bev","Murray","Denise","Al","Pat"}[c.Id%6]+" / "+c.Activity+": "+lines[c.Id%lines.Length]);c.Pause=2;}
 void StreetLifeSmoke(){if(traffic.Count<30||citizens.Count<30||signalNodes.Count<5)throw new InvalidDataException($"Street population missing: {traffic.Count}/{citizens.Count}/{signalNodes.Count}");var controlled=traffic.FirstOrDefault(t=>signalNodes.Contains(t.Link.To));if(controlled==null)throw new InvalidDataException("No signal-controlled traffic");float savedHour=state.Hour;float length=Vector2.Distance(carRouter.Nodes[controlled.Link.From],carRouter.Nodes[controlled.Link.To]);controlled.Distance=length-11;controlled.Point=CityPoint(controlled.Link,controlled.Distance);controlled.Speed=8;state.Hour=(CityRules.NorthSouth(carRouter.Nodes[controlled.Link.To]-carRouter.Nodes[controlled.Link.From])?35f:5f)/120;UpdateStreetLife(.1f);if(controlled.Speed!=0||controlled.Distance>length-10.9f)throw new InvalidDataException("Traffic crossed a red signal");state.Hour=savedHour;var before=traffic.Select(t=>t.Point).ToArray();var peopleBefore=citizens.Select(c=>c.Point).ToArray();for(int i=0;i<100;i++)UpdateStreetLife(.1f);if(!traffic.Where((t,i)=>Vector2.Distance(t.Point,before[i])>1).Any())throw new InvalidDataException("Traffic did not move");if(!citizens.Where((c,i)=>Vector2.Distance(c.Point,peopleBefore[i])>1).Any())throw new InvalidDataException("Pedestrians did not walk");if(!citizens.Any(c=>c.Route.Count>1))throw new InvalidDataException("Citizens have no scheduled routes");var node=signalNodes.OrderBy(n=>Vector2.DistanceSquared(carRouter.Nodes[n],truck)).First();position=carRouter.Nodes[node]+new Vector2(22,22);driving=false;interior=0;thirdPerson=true;cameraReady=false;yaw=MathHelper.PiOver4;Capture("street-life");var focus=controlled.Point;var travel=VehiclePhysics.Forward(controlled.Yaw);position=focus+new Vector2(-travel.Y,travel.X)*12-travel*14;if(Blocked(position))position=SidewalkPoint(focus);yaw=MathF.Atan2(-(focus-position).X,-(focus-position).Y);cameraReady=false;Capture("traffic-signals");float hour=state.Hour;state.Hour=22;for(int i=0;i<60;i++)UpdateStreetLife(.1f);if(citizens.Any(c=>c.Activity!="Home"))throw new InvalidDataException("Night home routine failed");Save();LoadSave();if(state.Hour!=22||traffic.Count<30||citizens.Count<30)throw new InvalidDataException("City clock/load failed");state.Hour=hour;Console.WriteLine($"PASS street life: {traffic.Count} traffic vehicles, {citizens.Count} citizens, {signalNodes.Count} inferred signal junctions; movement, scheduled routes, night routines and load.");}
